import Foundation
func check(_ value:Bool,_ message:String){if !value{fatalError(message)}}
check(DevelopmentReset.required(enabled:true,current:"9.8-27",previous:nil),"First opted-in build resets")
check(!DevelopmentReset.required(enabled:true,current:"9.8-27",previous:"9.8-27"),"Same build relaunch keeps progress")
check(DevelopmentReset.required(enabled:true,current:"9.8-28",previous:"9.8-27"),"New build resets")
check(!DevelopmentReset.required(enabled:false,current:"9.8-28",previous:"9.8-27"),"Production never resets")
let root=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString),support=root.appendingPathComponent("support"),caches=root.appendingPathComponent("caches")
try FileManager.default.createDirectory(at:support.appendingPathComponent("CocoPeople/Analyzer"),withIntermediateDirectories:true)
try FileManager.default.createDirectory(at:caches,withIntermediateDirectories:true)
try Data("old-signatures".utf8).write(to:caches.appendingPathComponent("ManoSizes.json"))
try Data("preserve".utf8).write(to:root.appendingPathComponent("photos-outside-sandbox"))
try Data("unrelated".utf8).write(to:support.appendingPathComponent("not-owned"))
try DevelopmentReset.eraseDerivedFiles(support:support,caches:caches)
try DevelopmentReset.eraseDerivedFiles(support:support,caches:caches)
check(!FileManager.default.fileExists(atPath:support.appendingPathComponent("CocoPeople").path),"Facial index removed, repeated reset idempotent")
check(!FileManager.default.fileExists(atPath:caches.appendingPathComponent("ManoSizes.json").path),"Derived metadata reset")
check(try Data(contentsOf:root.appendingPathComponent("photos-outside-sandbox"))==Data("preserve".utf8),"Photos outside sandbox untouched")
check(try Data(contentsOf:support.appendingPathComponent("not-owned"))==Data("unrelated".utf8),"Unrelated paths preserved")
// 9.8: retired People data is deleted on every launch, production included.
try FileManager.default.createDirectory(at:support.appendingPathComponent("CocoPeople/Reconciler"),withIntermediateDirectories:true)
try Data("index".utf8).write(to:support.appendingPathComponent("CocoPeople/index.sqlite"))
try FileManager.default.createDirectory(at:support.appendingPathComponent("CocoPeopleTrace"),withIntermediateDirectories:true)
try Data("{}".utf8).write(to:support.appendingPathComponent("CocoPeopleTrace/trace.json"))
check(LegacyPeopleCleanup.run(support:support)==2,"Facial index and trace removed")
check(LegacyPeopleCleanup.run(support:support)==0,"Cleanup is idempotent")
check(!FileManager.default.fileExists(atPath:support.appendingPathComponent("CocoPeople").path) && !FileManager.default.fileExists(atPath:support.appendingPathComponent("CocoPeopleTrace").path),"No face data left")
check(try Data(contentsOf:support.appendingPathComponent("not-owned"))==Data("unrelated".utf8),"Cleanup touches only retired folders")
try FileManager.default.removeItem(at:root)
print("SAFETY_OK: scoped developer reset and retired People data cleanup")
